const item = $input.item.json;
const raw = item.stdout || '';
const lines = raw.split('\n');
const exitLineIndex = lines.findIndex((l) => l.startsWith('DC005_EXIT_CODE='));
const exitCode = exitLineIndex >= 0 ? parseInt(lines[exitLineIndex].split('=')[1], 10) : null;
const jsonText = (exitLineIndex >= 0 ? lines.slice(0, exitLineIndex) : lines).join('\n').trim();
const workOrderId = $('Build Work Order Input').item.json.work_order_id;

let bridgeResult = null;
let parseError = null;
if (jsonText) {
  try {
    bridgeResult = JSON.parse(jsonText);
  } catch (e) {
    parseError = e.message;
  }
} else {
  parseError = 'Operations Bridge produced no stdout output.';
}

const validJsonResultProduced = bridgeResult !== null;
const hasDecision = validJsonResultProduced && typeof bridgeResult.decision === 'string';

let routeKey;
if (!validJsonResultProduced) {
  routeKey = 'technical_failure';
} else if (hasDecision) {
  routeKey = bridgeResult.decision;
} else {
  // A valid JSON body with success:false and no decision is I029.2/I029.3's
  // own thrown-error shape (eligibility/lock/configuration error) - a
  // technical failure, not an engineering decision. See operations-bridge.mjs's
  // own jsonFailureResult().
  routeKey = 'technical_failure';
}

return {
  json: {
    routeKey,
    validJsonResultProduced,
    exitCode,
    parseError,
    stderrExcerpt: (item.stderr || '').slice(0, 1000),
    workOrderId,
    ...(bridgeResult || {}),
  },
};
